function DonutChart() {
  // r=26, circumference ≈ 163.4
  // purple segment 58% → 94.8, orange 42% → 68.6
  const r = 26
  const cx = 36
  const cy = 36
  const circ = 2 * Math.PI * r
  const purpleLen = circ * 0.58
  const orangeLen = circ * 0.42
  const offset = circ / 4 // start from top

  return (
    <svg viewBox="0 0 72 72" className="h-full w-full">
      {/* track */}
      <circle cx={cx} cy={cy} r={r} fill="none" stroke="#e9d5f5" strokeWidth="11" />
      {/* purple segment */}
      <circle
        cx={cx}
        cy={cy}
        r={r}
        fill="none"
        stroke="#7b3699"
        strokeWidth="11"
        strokeDasharray={`${purpleLen} ${circ - purpleLen}`}
        strokeDashoffset={offset}
        strokeLinecap="butt"
      />
      {/* orange segment */}
      <circle
        cx={cx}
        cy={cy}
        r={r}
        fill="none"
        stroke="#FF8300"
        strokeWidth="11"
        strokeDasharray={`${orangeLen} ${circ - orangeLen}`}
        strokeDashoffset={offset - purpleLen}
        strokeLinecap="butt"
      />
    </svg>
  )
}

